 * tools 清单收敛 = 只剩笔记两键（记忆写回不经工具——回信即交付物）；
 * 其父 role 刻意不设 tools（匿名不封顶），grant 逐键仍被出生表钳制。
 */
export const DREAMER_SPEC: AgentClass = {
  name: makeAgentClassID('cortex-dreamer'),
