    // cortex 的宿主自动持有；逐键仍被出生表与祖先显式判定封顶。
    tools: {
      cortex_add_note: 'allow',
      cortex_del_note: 'allow',
    },
    // 记忆组是真实行 → 组装恒直出（教学样板在写入端完成，读取端零特殊）。
    assemble: classicAssemble,
    init: async (ctx: StrategyInitContext): Promise<void> => {
      fsRef = ctx.fs
