      parseCortexSettings({ cortex: { dreamAt: DEFAULT_DREAM_AT } }, ctx.settings.window, (message) =>
        ctx.log.log({ type: 'context.dreamed', at: Date.now(), agentId: '*', consolidated: false, invalidRows: 0, notesTouched: 0, message }),
      )
