      }
      // ② 阈值点火：过线且全局无梦 → 后台做梦（本轮送信照常，不等收口）。
      if (runtime.dream !== undefined) return
      const settings = settingsFor(api)
      if (api.estimatedTokens() < settings.dreamAt) return
      void runDream(api, settings, dreamDeps())
        .then((outcome) => {
