        st.warned.add(message)
        api.log({ type: 'context.dreamed', agentId: api.agentId, consolidated: false, invalidRows: 0, notesTouched: 0, message: `配置 ${message}` })
      }
    })

  const dreamDeps = (): DreamDeps => ({
    runtime,
    fsRef: () => fsRef,
    projectRoot,
    memDirOf,
  })

