  const { runtime } = deps
  if (runtime.dream !== undefined) {
    return { consolidated: false, invalidRows: 0, notesTouched: 0, message: '已有梦在途（全局串行），本场跳过' }
  }
  const hostId = api.agentId
  const token = runtime.begin(hostId)

